def f(inp):
    H,W=len(inp),len(inp[0])
    # key bar: row with >=4 distinct nonzero colors
    key=None; brr=None
    for r in range(H):
        vals={v for v in inp[r] if v}
        if len(vals)>=3 and all(c!=inp[r][0] or True for c in []): pass
        nz=[c for c in range(W) if inp[r][c]]
        row=[inp[r][c] for c in nz]
        uniq=list(set(row))
        if len(uniq)>=3 and all(inp[r][c]==uniq[nz.index(u)] for u in uniq for c in range(W) if inp[r][c]==u):
            pass
        break
    # simpler: the key bar is a contiguous horizontal run where each cell differs
    for r in range(H):
        run=[]
        ok=True
        prev=None
        for c in range(W):
            v=inp[r][c]
            if v and (prev is None or v!=prev):
                if prev is not None and c==len(run)+1: pass
        break
    # find longest horizontal run of nonzeros with all distinct
    best=[]
    for r in range(H):
        c=0
        while c<W:
            if inp[r][c]:
                d=c
                while d+1<W and inp[r][d+1]!=0 and inp[r][d+1]!=inp[r][d]: d+=1
                if d-c>=2 and (best==[] or d-c>len(best)): best=[r,c,d]
            else: c+=1
    r0,k0,k1=best
    key=[inp[r0][c] for c in range(k0,k1+1)]
    out=[row[:] for row in inp]
    # shapes: largest component per color (excluding key bar region rows r0-1..r0+1 cols k0..k1)
    bar={(r,c) for r in range(max(0,r0-1),min(H-1,r0+2)) for c in range(k0,k1+1)}
    shapes={}
    for col in set(v for row in inp for v in row if v):
        for comp in comps(inp,col):
            if not any(p in bar for p in comp) and len(comp)>1:
                shapes.setdefault(col,comp)
    anchor=[col for col in key if col in shapes][0]
    acells=shapes[anchor]
    mr=min(y for y,_ in acells); mc=min(x for _,x in acells)
    h=max(y for y,_ in acells)-mr+1; w=max(x for _,x in acells)-mc+1
    pat={(y-mr,x-mc) for y,x in acells}
    mpat={(y,x) for y,x in [(a,h-1-b) for a,b in pat]}
    def paint(col,ry):
        for dy,dx in mpat:
            out[ry+dy][mc+dx]=col
    above=[]; below=[]
    for i,kv in enumerate(key):
        if kv in shapes and kv!=anchor: continue
        idx=key.index(kv)
        if idx<key.index(anchor): above.append(kv)
        else: below.append(kv)
    cur=top-ht-1   # will fix
    # anchor top row
    top=min(y for y,_ in acells)
    cur=top-h-1
    for kv in above: paint(kv,int(cur)); cur-=h
    cur=top+1
    for kv in below: paint(kv,int(cur)); cur+=h
    return out

